test("45 度回したノードの回った右下の角の帯を押すと、幅と高さの両方を掴む", () => {
  // 回る前の (293, 143)。描いた角の四角の外側・帯の内側
  const onCornerBands = RotatedBounds.pointAt(TurnedBounds, {
    x: 0.965,
    y: 0.93,
  });

  const grabbed = NodeResize.grabAt(
    placedTurned({ own: 45, total: 45 }),
    TurnedBounds,
    onCornerBands,
  );

  expect(Option.map(grabbed, (held) => held.grip)).toEqual(
    Option.some({
      kind: "both",
      width: { length: { axis: "width", length: 200 }, end: "end" },
      height: { length: { axis: "height", length: 100 }, end: "end" },
    }),
  );
});

test("右下の角の帯を掴んで斜めに運ぶと、幅と高さが 1 回の編集で通知される", () => {
  // 描いた角の四角の外側・帯の内側を押す
  const onResize = vi.fn();
  renderCanvas({ selection: setupSelection(["panel"]), onResize });
  const panel = drawnAt("panel", PanelBounds);

  pressPointer(panel, { x: 293, y: 143 });
  movePointer(panel, { x: 333, y: 168 });
  releasePointer(panel, { x: 333, y: 168 });

  expect(onResize).toHaveBeenLastCalledWith(
    ResizeEdit.create([
      { axis: "width", length: 240 },
      { axis: "height", length: 125 },
    ]),
    expect.anything(),
  );
});

test("右下の角の帯を掴んでいる間は、器が斜めのカーソルを出す", () => {
  renderCanvas({ selection: setupSelection(["panel"]) });
  const panel = drawnAt("panel", PanelBounds);

  pressPointer(panel, { x: 293, y: 143 });

  expect(canvasContent().style.cursor).toBe("nwse-resize");
});

function axisGrabAt(
  resizable: ResizableSelection,
  axis: Axis,
  pointedEnd: Option<AxisEnd>,
): Option<AxisGrab> {
  return Option.flatMap(pointedEnd, (end) =>
    Option.flatMap(AxisLength.find(resizable.lengths, axis), (length) =>
      grabFor(resizable, length, end),
    ),
  );
}

function combinedGrip(
  width: Option<AxisGrab>,
  height: Option<AxisGrab>,
): Option<ResizeGrip> {
  // 名前を付けた変数にすると narrowing が効かないので、条件はここへ直に書く
  if (Option.isSome(width) && Option.isSome(height)) {
    return Option.some({
      kind: "both",
      width: width.value,
      height: height.value,
    });
  }
  return Option.map(Option.or(width, height), ResizeGrip.create);
}

function bandEndAt(
  bounds: CanvasBounds,
  pointer: Offset,
  axis: Axis,
): Option<AxisEnd> {
  const along = Offset.along(pointer, axis);
  const distanceTo = (end: AxisEnd): number =>
    Math.abs(CanvasBounds.edgeAt(bounds, axis, end) - along);
  const nearest = Object.values(AxisEnds).reduce((nearer, end) =>
    distanceTo(end) < distanceTo(nearer) ? end : nearer,
  );
  return distanceTo(nearest) <= ResizeHandleThicknessPx
    ? Option.some(nearest)
    : Option.none;
}
